ANNOTATIONS = [
    (51, 'before', r'''条件 require 防 tree-shaking：autoModeState / permissionSetup 两个模块只在 TRANSCRIPT_CLASSIFIER 特性开启时才引入。若用静态 import，被打包进主 chunk 的顶层副作用（如 autoModeState 的模块级 memoize）会在特性关闭时依然存活——条件 require 让打包器彻底看不到这条路径。'''),
    (60, 'before', r'''allowedPromptSchema：计划可「语义化」申请权限类别（如「跑测试」「装依赖」）而非逐条命令。这是 exit plan mode 与权限系统的接缝——计划里声明要干什么，用户批准计划即批量批准一类动作。tool 目前只开放 Bash。'''),
    (77, 'before', r'''inputSchema 本体：strictObject + passthrough。严格校验未知字段（防模型幻觉参数），但 passthrough 又允许它们通过——因为 normalizeToolInput 会从磁盘注入 plan/planFilePath，而这两字段刻意不进内部 schema（计划内容从文件读，不进上下文两次）。'''),
    (92, 'before', r'''_sdkInputSchema 是 SDK/Hook 面的 schema：把 normalizeToolInput 注入的 plan 与 planFilePath 显式声明出来。内外两套 schema 的差异正是「注入发生在权限校验之后」这一事实的化石。'''),
    (110, 'before', r'''outputSchema 字段即状态机快照：计划文本、是否 agent 上下文、落盘路径、有没有 Agent 工具（决定要不要提示拆团队）、用户是否编辑过计划（决定 tool_result 里回显时打什么标签）、是否在等队长审批、审批请求 ID。'''),
    (147, 'before', r'''buildTool 主结构。与 EnterPlanModeTool 的 isEnabled 完全对称——channels 防护成对出现（详见 EnterPlanModeTool 同段批注）。'''),
    (167, 'before', r'''isEnabled：--channels 下用户在 Telegram/Discord，计划审批对话框会永久挂起，故整体禁用。注释明说与 EnterPlanMode「成对」——单边禁用会让模型进得去出不来。'''),
    (182, 'before', r'''isReadOnly 返回 false——V2 与 V1 的最大分野：计划要落盘（writeFile），从此它是只读工具家族里的异类。EnterPlanMode 仍是只读。'''),
    (185, 'before', r'''requiresUserInteraction：teammate 一律不等本地用户——强制计划的队走 mailbox 等队长审批，自愿计划的队本地直接退出；非 teammate 必须用户点头。同一工具三种交互姿态。'''),
    (195, 'before', r'''validateInput 两段式。teammate 直接放行：队友的 AppState 里可能是队长的模式（runAgent.ts 在 acceptEdits/bypassPermissions/auto 下跳过覆盖），isPlanModeRequired() 才是真相源——AppState 会骗人，专用查询函数不会。'''),
    (205, 'before', r'''非 plan 模式调用的拒绝逻辑：deferred 工具列表无论当前模式都会广播本工具（压缩/清上下文后的新 delta 里模型还能看见它），所以必须在 checkPermissions 之前拦截——否则用户会看到一个莫名其妙的「退出计划模式？」审批框。拒绝同时打 tengu_exit_plan_mode_called_outside_plan 遥测，这是模型对自身状态失察的量化指标。'''),
    (221, 'before', r'''checkPermissions：teammate 完全绕过权限 UI（不弹框、不发 permission_request），交互逻辑全部挪进 call()；非 teammate 走 ask——「Exit plan mode?」这个对话框是计划模式的正式出口。'''),
    (243, 'before', r'''call() 开头的三件事：isAgent 标记（子代理里批准计划后只需回个 ok）、定位计划文件、取计划内容。'''),
    (253, 'before', r'''inputPlan 的来源窄化：CCR web UI 允许用户在权限对话框里编辑计划，编辑结果经 permissionResult.updatedInput 回传；queryHelpers.ts 是全量替换 finalInput，CCR 不编辑时传 {}，input.plan 即为 undefined——于是窄化成「有字符串才算编辑过」，否则回落读磁盘。三元表达式只认 typeof string，数字/对象一律视为未提供。'''),
    (258, 'before', r'''编辑回写磁盘：VerifyPlanExecution 与 Read 都要看到编辑后的计划。 persistFileSnapshotIfRemote 必须再调一次——api.ts 里那次快照跑在 normalizeToolInput（权限前），拍到的是旧计划。快照时序是远程协作场景的隐藏接缝。'''),
    (264, 'before', r'''teammate + isPlanModeRequired 分支：没写计划文件直接抛错（计划是强制产物，不允许空计划过关）；有则生成 plan_approval_request 写进 team-lead  mailbox——审批走消息队列而非本地对话框，异步协作的全部要义。'''),
    (327, 'before', r'''熔断防御：prePlanMode 是 auto 但 auto 模式闸门已关（熔断或设置禁用）时，恢复目标降级为 default 并发通知。没有这段，ExitPlanMode 会绕过熔断器直接 setAutoModeActive(true)——退出计划模式成了自动模式的「侧门」。'''),
    (357, 'before', r'''setAppState 恢复现场：prePlanMode 还原进计划前的模式；auto 状态以 isAutoModeActive() 为权威（prePlanMode/strippedDangerousRules 在 transitionPlanAutoMode 中途停用后已过期）；恢复非 auto 模式时把进计划前剥掉的危险规则还原，恢复 auto 则保持剥离——退出不是简单的模式回滚，而是权限集合的对称复原。'''),
    (405, 'before', r'''hasTaskTool 探测：Agent 工具在当前上下文可用且 agent swarms 开启时，tool_result 里追加「可拆团队并行」的提示——计划批准点是并行化的自然决策点。'''),
    (419, 'before', r'''tool_result 生成四分支：等队长审批（列后续步骤 + 禁止擅动）/ agent 上下文（一句 ok 打发）/ 空计划（一句放行）/ 正常（回显计划全文 + 保存路径 + 团队提示）。'''),
    (474, 'before', r'''计划全文必须总是回显——Ultraplan CCR 流程的 extractApprovedPlan() 要解析 tool_result 才能把计划文本喂给本地 CLI。用户编辑过的计划打「edited by user」标签：模型必须知道用户改过它的方案，否则会按记忆里的旧版实施。'''),
    (481, 'before', r'''最终 tool_result 组装：批准语 + 保存路径（可 /plan 随时回看）+ 条件团队提示 + 计划全文。路径回显是给模型的锚点——实现阶段引用计划不用重新探索。'''),
]
